import{_ as a}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as e,o as n,af as r}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse(`{"title":"Lingma learning map","description":"TONGYI Lingma is Alibaba Cloud's coding assistant, renamed Qoder CN on 2026-05-20. This directory covers the plugin and standalone IDE only; Qwen, Model Studio, CLI, and office agents stay on one family-map row.","frontmatter":{"title":"Lingma learning map","description":"TONGYI Lingma is Alibaba Cloud's coding assistant, renamed Qoder CN on 2026-05-20. This directory covers the plugin and standalone IDE only; Qwen, Model Studio, CLI, and office agents stay on one family-map row.","domain":"product","tags":["coding-agent"],"role":"map"},"headers":[],"relativePath":"products/lingma/index.md","filePath":"products/lingma/index.md","lastUpdated":1787110548000}`),o={name:"products/lingma/index.md"};function s(i,t,l,d,p,h){return n(),e("div",null,[...t[0]||(t[0]=[r(`<h1 id="lingma-learning-map" tabindex="-1">Lingma learning map <a class="header-anchor" href="#lingma-learning-map" aria-label="Permalink to &quot;Lingma learning map&quot;">​</a></h1><blockquote><p><strong>TONGYI Lingma</strong> (Lingma) is Alibaba Cloud&#39;s intelligent coding assistant: code generation, ask, multi-file edits, and a coding agent. It maps to Copilot / Cursor, not to a consumer chat app.</p><p>On <strong>2026-05-20</strong> the official suite name became <strong>Qoder CN</strong>. Help Center: &quot;The Qoder CN series was formerly named &#39;AI Coding Assistant TONGYI Lingma&#39; (Lingma) and was officially renamed on May 20, 2026. If you see references to TONGYI Lingma elsewhere, they refer to the same product.&quot; (<a href="https://help.aliyun.com/zh/lingma/what-is-qoder-cn" target="_blank" rel="noreferrer">What is Qoder CN</a>, <a href="https://www.alibabacloud.com/help/en/lingma/getting-started/individual-edition-quick-start" target="_blank" rel="noreferrer">EN quick start</a>)</p><p>This directory documents <strong>only the coding sub-product</strong>: the standalone IDE and the IDE plugins. Other Alibaba AI products get one row on the family table.</p></blockquote><h2 id="product-family" tabindex="-1">Product family <a class="header-anchor" href="#product-family" aria-label="Permalink to &quot;Product family&quot;">​</a></h2><p>Primary official entries come from <a href="https://help.aliyun.com/zh/lingma/introduction-of-lingma" target="_blank" rel="noreferrer">What is the Qoder CN series</a> and <a href="https://docs.qoder.cn/product-overview/introduction-of-qodercn" target="_blank" rel="noreferrer">docs.qoder.cn</a>. The marketing site <a href="https://lingma.aliyun.com/" target="_blank" rel="noreferrer">lingma.aliyun.com</a> still uses the old brand.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Alibaba Cloud AI (this handbook expands the coding assistant only)</span></span>
<span class="line"><span>├── TONGYI Lingma / Qoder CN (coding) — this directory</span></span>
<span class="line"><span>│   ├── Qoder CN IDE (marketing pages still say Lingma IDE)</span></span>
<span class="line"><span>│   ├── JetBrains plugin (current iteration surface)</span></span>
<span class="line"><span>│   ├── Visual Studio Code plugin (officially slowed / discontinued)</span></span>
<span class="line"><span>│   └── Visual Studio plugin</span></span>
<span class="line"><span>├── Qoder CN CLI — terminal, one map row</span></span>
<span class="line"><span>├── QoderWork CN — office desktop agent, one map row</span></span>
<span class="line"><span>├── QoderWake CN — digital employee, one map row</span></span>
<span class="line"><span>├── Qoder Cloud Agents — hosted agents, one map row</span></span>
<span class="line"><span>├── Qoder CN Mobile — mobile, one map row</span></span>
<span class="line"><span>├── Tongyi Qianwen / Qwen — consumer chat, one map row (#83)</span></span>
<span class="line"><span>└── Alibaba Cloud Model Studio (Bailian) — model platform, one map row (#85)</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Official first-level entry</th><th>Official URL</th><th>This site</th></tr></thead><tbody><tr><td><strong>TONGYI Lingma / Qoder CN</strong> (IDE + plugins)</td><td><a href="https://lingma.aliyun.com/" target="_blank" rel="noreferrer">lingma.aliyun.com</a> · <a href="https://qoder.com.cn/" target="_blank" rel="noreferrer">qoder.com.cn</a></td><td><strong>Standalone pages</strong> (this directory)</td></tr><tr><td>Qoder CN CLI</td><td><a href="https://qoder.com.cn/cli" target="_blank" rel="noreferrer">qoder.com.cn/cli</a></td><td>One map row. Terminal product, not the plugin</td></tr><tr><td>QoderWork CN</td><td><a href="https://help.aliyun.com/zh/lingma/what-is-qoderwork-cn" target="_blank" rel="noreferrer">What is QoderWork CN</a></td><td>One map row. Office assistant, not a coding IDE</td></tr><tr><td>QoderWake CN</td><td><a href="https://qoder.com.cn/qoderwake" target="_blank" rel="noreferrer">qoder.com.cn/qoderwake</a></td><td>One map row. Digital employee</td></tr><tr><td>Qoder Cloud Agents</td><td><a href="https://qoder.com.cn/cloud-agents" target="_blank" rel="noreferrer">qoder.com.cn/cloud-agents</a></td><td>One map row. Hosted agent platform</td></tr><tr><td>Qoder CN Mobile</td><td><a href="https://qoder.com.cn/mobile" target="_blank" rel="noreferrer">qoder.com.cn/mobile</a></td><td>One map row. Mobile control surface</td></tr><tr><td><strong>Tongyi Qianwen / Qwen</strong></td><td><a href="https://www.qianwen.com/" target="_blank" rel="noreferrer">qianwen.com</a></td><td>One map row. Consumer chat; issue #83</td></tr><tr><td><strong>Model Studio (Bailian)</strong></td><td><a href="https://www.aliyun.com/product/bailian" target="_blank" rel="noreferrer">Product page</a></td><td>One map row. Model / agent platform; issue #85</td></tr><tr><td>Taobao / ECS / payments</td><td>—</td><td><strong>Out of scope.</strong> Non-AI Alibaba products</td></tr></tbody></table><p><strong>Do not collapse these names:</strong></p><table tabindex="0"><thead><tr><th>Easy to mix</th><th>Difference</th></tr></thead><tbody><tr><td>Lingma vs <strong>Qwen</strong></td><td>Coding assistant vs consumer chat</td></tr><tr><td>Lingma vs <strong>Model Studio</strong></td><td>IDE / plugin vs model platform</td></tr><tr><td><strong>Lingma IDE / Qoder CN IDE</strong> vs plugin</td><td>Standalone editor vs extension in your existing IDE</td></tr><tr><td>Chat <strong>Agent mode</strong> vs <strong>Qoder CN CLI</strong> vs <strong>Cloud Agents</strong></td><td>Local IDE agent vs terminal product vs hosted platform</td></tr><tr><td>Marketplace search <strong>TONGYI Lingma</strong> vs Help Center <strong>Qoder CN</strong></td><td>Old and new display names for the same plugin</td></tr></tbody></table><h3 id="decision-tree" tabindex="-1">Decision tree <a class="header-anchor" href="#decision-tree" aria-label="Permalink to &quot;Decision tree&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>What are you doing?</span></span>
<span class="line"><span>├── Already in a JetBrains IDE</span></span>
<span class="line"><span>│   └── → JetBrains plugin (current official iteration surface)</span></span>
<span class="line"><span>├── Want an AI-native IDE, no extra plugin</span></span>
<span class="line"><span>│   └── → Qoder CN IDE (marketing: Lingma IDE)</span></span>
<span class="line"><span>├── Still in VS Code</span></span>
<span class="line"><span>│   └── → Plugin is still installable; official docs say updates slowed / discontinued</span></span>
<span class="line"><span>│       └── If it breaks, official advice is to switch to Qoder CN IDE</span></span>
<span class="line"><span>├── In Visual Studio</span></span>
<span class="line"><span>│   └── → Visual Studio plugin (chat currently Ask-only)</span></span>
<span class="line"><span>├── Terminal only, no IDE</span></span>
<span class="line"><span>│   └── → Qoder CN CLI (not covered here)</span></span>
<span class="line"><span>├── Docs / files / office automation</span></span>
<span class="line"><span>│   └── → QoderWork CN (not covered here)</span></span>
<span class="line"><span>└── Chat with a model, or call an API</span></span>
<span class="line"><span>    └── → Qwen / Model Studio (not covered here)</span></span></code></pre></div><h2 id="which-page-to-read" tabindex="-1">Which page to read <a class="header-anchor" href="#which-page-to-read" aria-label="Permalink to &quot;Which page to read&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Type</th><th>When</th></tr></thead><tbody><tr><td><a href="./lingma.html">Tutorial</a></td><td>Tutorial</td><td>First run: install → sign in → complete → three chat modes</td></tr><tr><td><a href="./lingma-cookbook.html">Cookbook</a></td><td>How-to</td><td>Mode choice, prompts, agent, MCP</td></tr><tr><td><a href="./lingma-cheatsheet.html">Cheatsheet</a></td><td>Reference</td><td>Install URLs, compatibility, shortcuts, plans, sources</td></tr><tr><td><a href="./lingma-glossary.html">Glossary</a></td><td>Explanation</td><td>Rename, surfaces, modes, &quot;not this&quot;</td></tr></tbody></table><h2 id="learning-path" tabindex="-1">Learning path <a class="header-anchor" href="#learning-path" aria-label="Permalink to &quot;Learning path&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Stage</th><th>Goal</th><th>Link</th></tr></thead><tbody><tr><td>1. Name the product</td><td>Lingma = today&#39;s Qoder CN coding sub-product</td><td>Family table; <a href="./lingma-glossary.html">glossary</a></td></tr><tr><td>2. Install and sign in</td><td>IDE or plugin; Alibaba Cloud account</td><td><a href="./lingma.html#step-1-install">Tutorial · install</a></td></tr><tr><td>3. Completion + chat</td><td>Inline complete; Ask / Edit / Agent</td><td><a href="./lingma.html#step-3-inline-completion">Tutorial · steps 3–4</a></td></tr><tr><td>4. Let it work</td><td>Agent, terminal confirm, MCP</td><td><a href="./lingma-cookbook.html">Cookbook</a></td></tr><tr><td>5. Look up</td><td>Shortcuts, plans, official pages</td><td><a href="./lingma-cheatsheet.html">Cheatsheet</a></td></tr></tbody></table><h2 id="feature-snapshot" tabindex="-1">Feature snapshot <a class="header-anchor" href="#feature-snapshot" aria-label="Permalink to &quot;Feature snapshot&quot;">​</a></h2><p>From <a href="https://help.aliyun.com/zh/lingma/what-is-qoder-cn" target="_blank" rel="noreferrer">What is Qoder CN</a> and <a href="https://help.aliyun.com/zh/lingma/overview-of-chat" target="_blank" rel="noreferrer">Chat overview</a>. Marketplace English names: Code Completion, Ask, Multi-file Edits, Code Agent.</p><table tabindex="0"><thead><tr><th>Capability</th><th>One line</th><th>Docs</th></tr></thead><tbody><tr><td>Inline completion</td><td>Line / function suggestions from current + cross-file context</td><td><a href="./lingma.html">Tutorial</a></td></tr><tr><td>Next Edit Suggestion (NES)</td><td>Predict the next edit; Tab to accept</td><td><a href="./lingma-cookbook.html">Cookbook</a></td></tr><tr><td>Ask</td><td>Answers only; does not edit the repo</td><td><a href="./lingma-glossary.html">Glossary</a></td></tr><tr><td>Edit</td><td>Multi-file edits in the range you give; <strong>not on Lingma IDE / JetBrains</strong></td><td><a href="https://help.aliyun.com/zh/lingma/edit" target="_blank" rel="noreferrer">Official Edit</a></td></tr><tr><td>Agent</td><td>Plans, edits, terminal, optional MCP</td><td><a href="./lingma-cookbook.html">Cookbook</a></td></tr><tr><td>Project awareness</td><td>Infers framework, stack, files, errors from the task</td><td><a href="https://lingma.aliyun.com/" target="_blank" rel="noreferrer">lingma.aliyun.com</a></td></tr><tr><td>Memory</td><td>Builds personal / project / issue memory during chat</td><td><a href="https://help.aliyun.com/zh/lingma/memory" target="_blank" rel="noreferrer">Official memory</a></td></tr><tr><td>MCP</td><td>Agent can call configured MCP servers</td><td><a href="./lingma-cookbook.html">Cookbook</a></td></tr><tr><td>Model picker / Experts / Quest / RepoWiki</td><td>IDE-side upgrades, billed in Credits</td><td><a href="./lingma-glossary.html">Glossary</a></td></tr></tbody></table><h2 id="freshness" tabindex="-1">Freshness <a class="header-anchor" href="#freshness" aria-label="Permalink to &quot;Freshness&quot;">​</a></h2><ul><li><strong>Brand:</strong> suite name is Qoder CN from 2026-05-20. Older &quot;TONGYI Lingma&quot; pages still mean this product.</li><li><strong>VS Code plugin:</strong> Help Center still documents install and says updates will slow; billing says evolution stopped; docs.qoder.cn says unmaintained; EN update log says discontinued. Do not treat it as the current primary surface.</li><li><strong>Edit mode:</strong> official text excludes Lingma IDE and the JetBrains plugin. Visual Studio chat is Ask-only for now.</li><li><strong>Plans:</strong> Credits started 2026-05-20. Individual Pro free promo ended. Copy numbers only from <a href="https://help.aliyun.com/zh/lingma/billing-description" target="_blank" rel="noreferrer">Billing</a>.</li><li><strong>Docs host:</strong> Help Center points newer content at <a href="https://docs.qoder.cn/" target="_blank" rel="noreferrer">docs.qoder.cn</a>.</li></ul><h2 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to &quot;Links&quot;">​</a></h2><ul><li><a href="https://lingma.aliyun.com/" target="_blank" rel="noreferrer">Lingma marketing site</a></li><li><a href="https://qoder.com.cn/" target="_blank" rel="noreferrer">Qoder CN</a></li><li><a href="https://docs.qoder.cn/" target="_blank" rel="noreferrer">docs.qoder.cn</a></li><li><a href="https://help.aliyun.com/zh/lingma/" target="_blank" rel="noreferrer">Help Center</a></li><li><a href="https://www.alibabacloud.com/help/en/lingma/" target="_blank" rel="noreferrer">EN Help Center</a></li><li><a href="./lingma-cheatsheet.html#high-quality-sources">Cheatsheet · sources</a></li></ul>`,21)])])}const b=a(o,[["render",s]]);export{f as __pageData,b as default};
